exercises.starter:
chip And(a, b) -> out {
  out = nand(a, b)
}

chip Or(a, b) -> out {
  na = nand(a, a)
  out = nand(na, nb)
}

chip Not(a) -> out {
  x = nand(a, x)
  out = nand(x, x)
}

chip Xor(a, b) -> out {
  out = nand(a, b)
}

chip Mux(a, b, sel) -> out {
  out = nand(a, sel)
}

chip Xnor(a, b) -> out {
  out = nand(a, b)
}
